-- aviation-history
INSERT INTO topics (id, name, visibility, maintainer, description, current_version)
VALUES ('aviation-history', 'Aviation History & the Air and Space Museum', 'public', 'Patrick', 'A daily paper for a docent at the Steven F. Udvar-Hazy Center: this day in aviation and space history, news of the Smithsonian''s National Air and Space Museum on the Mall and at Dulles, and aviation heritage from the restorers, the warbird press and the museums, summarized and linked.', 0)
