INSERT INTO topics (id, name, visibility, maintainer, description, current_version)
VALUES ('global-us-news', 'Global and U.S. News', 'public', 'Patrick', 'The day''s significant news, worldwide and in the United States, as surfaced by the New York Times, the Economist and the Wall Street Journal, organized by the Economist''s sections, with the top two or three stories in each, summarized and linked.', 0)
ON CONFLICT(id) DO UPDATE SET
  name = excluded.name, visibility = excluded.visibility, maintainer = excluded.maintainer,
  description = excluded.description, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now');

INSERT INTO topic_versions (topic_id, version, definition, note)
SELECT 'global-us-news',
       COALESCE((SELECT MAX(version) FROM topic_versions WHERE topic_id = 'global-us-news'), 0) + 1,
       '{"id":"global-us-news","name":"Global and U.S. News","visibility":"public","maintainer":"Patrick","description":"The day''s significant news, worldwide and in the United States, as surfaced by the New York Times, the Economist and the Wall Street Journal, organized by the Economist''s sections, with the top two or three stories in each, summarized and linked.","cadence":"twice daily, runs at 05:05 and 17:05 America/New_York (09:05 and 21:05 UTC in daylight time); the later run is the edition for the day and earlier runs fold beneath it","edition_size":"2 to 3 stories per subtopic unless the subtopic sets max_stories; a subtopic with nothing significant is omitted","subtopics":[{"id":"leaders","name":"Leaders","weight":1},{"id":"briefing","name":"Briefing","weight":1},{"id":"united-states","name":"United States","weight":1},{"id":"international","name":"International","weight":1},{"id":"finance-and-economics","name":"Finance and economics","weight":1,"max_stories":4},{"id":"business","name":"Business","weight":1,"max_stories":4},{"id":"europe","name":"Europe","weight":1},{"id":"asia","name":"Asia","weight":1},{"id":"china","name":"China","weight":1},{"id":"middle-east-and-africa","name":"Middle East and Africa","weight":1},{"id":"the-americas","name":"The Americas","weight":1},{"id":"science-and-technology","name":"Science and technology","weight":1}],"subtopic_notes":["Weights are all 1.0 at launch. They exist so that personal signals and a later private view can reweight them without changing the topic''s shape.","''The world this week'' is read as agenda only; it is a digest, not a subtopic.","Every candidate, from any source, is assigned to exactly one subtopic by the agent. NYT feeds map naturally: World to the regional subtopics, U.S. and Politics to United States, Business to Business or Finance and economics.","WSJ feeds map: World to the regional subtopics or International, US Business to Business, Markets to Finance and economics."],"entities":[],"deprioritize":["celebrity and entertainment news","sports, except an event of national or international consequence","individual crime stories without systemic significance","opinion and commentary, unless the edition is explicitly surfacing a leader","incremental product announcements","live-blog and ''what we know'' rolling formats"],"agenda_sources":[{"publisher":"New York Times","window_hours":48,"feeds":[{"name":"Home page","url":"https://rss.nytimes.com/services/xml/rss/nyt/HomePage.xml"},{"name":"World","url":"https://rss.nytimes.com/services/xml/rss/nyt/World.xml"},{"name":"U.S.","url":"https://rss.nytimes.com/services/xml/rss/nyt/US.xml"},{"name":"Politics","url":"https://rss.nytimes.com/services/xml/rss/nyt/Politics.xml"},{"name":"Business","url":"https://rss.nytimes.com/services/xml/rss/nyt/Business.xml"}],"role":"agenda"},{"publisher":"The Economist","window_hours":168,"feeds":[{"name":"The world this week","url":"https://www.economist.com/the-world-this-week/rss.xml","agenda_only_digest":true},{"name":"Leaders","url":"https://www.economist.com/leaders/rss.xml"},{"name":"Briefing","url":"https://www.economist.com/briefing/rss.xml"},{"name":"United States","url":"https://www.economist.com/united-states/rss.xml"},{"name":"International","url":"https://www.economist.com/international/rss.xml"},{"name":"Finance and economics","url":"https://www.economist.com/finance-and-economics/rss.xml"},{"name":"Business","url":"https://www.economist.com/business/rss.xml"},{"name":"Europe","url":"https://www.economist.com/europe/rss.xml"},{"name":"Asia","url":"https://www.economist.com/asia/rss.xml"},{"name":"China","url":"https://www.economist.com/china/rss.xml"},{"name":"Middle East and Africa","url":"https://www.economist.com/middle-east-and-africa/rss.xml"},{"name":"The Americas","url":"https://www.economist.com/the-americas/rss.xml"},{"name":"Science and technology","url":"https://www.economist.com/science-and-technology/rss.xml"}],"window_note":"The Economist publishes its weekly edition on Thursday and Friday and only a few items on other days, so a 48-hour window misses most of it after Saturday. Seven days makes the whole current issue agenda; the archive prevents repeats.","role":"agenda"},{"publisher":"Wall Street Journal","role":"agenda","window_hours":48,"feeds":[{"name":"World","url":"https://feeds.content.dowjones.io/public/rss/RSSWorldNews"},{"name":"US Business","url":"https://feeds.content.dowjones.io/public/rss/WSJcomUSBusiness"},{"name":"Markets","url":"https://feeds.content.dowjones.io/public/rss/RSSMarketsMain"}],"note":"Promoted from signal to agenda 2026-10-18 by the owner: a differently positioned U.S. desk with the strongest business and markets coverage of the set. US News and Politics feeds no longer exist; Opinion left out like Economist Leaders."},{"publisher":"BBC","role":"signal","window_hours":48,"feeds":[{"name":"World","url":"https://feeds.bbci.co.uk/news/world/rss.xml"},{"name":"US and Canada","url":"https://feeds.bbci.co.uk/news/world/us_and_canada/rss.xml"}]},{"publisher":"NPR","role":"signal","window_hours":48,"feeds":[{"name":"News","url":"https://feeds.npr.org/1001/rss.xml"}]},{"publisher":"The Guardian","role":"signal","window_hours":48,"feeds":[{"name":"World","url":"https://www.theguardian.com/world/rss"},{"name":"US","url":"https://www.theguardian.com/us-news/rss"}]},{"publisher":"Al Jazeera","role":"signal","window_hours":48,"feeds":[{"name":"All","url":"https://www.aljazeera.com/xml/rss/all.xml"}]},{"publisher":"Financial Times","role":"signal","window_hours":48,"feeds":[{"name":"World","url":"https://www.ft.com/world?format=rss"}]},{"publisher":"Science press","role":"signal","window_hours":72,"feeds":[{"name":"Nature news","url":"https://www.nature.com/nature.rss"},{"name":"Science news","url":"https://www.science.org/rss/news_current.xml"},{"name":"MIT Technology Review","url":"https://www.technologyreview.com/feed/"}],"note":"Added 2026-10-17 after the Science and technology subtopic ran empty on a night when its only candidates were Economist analysis pieces. 72-hour window because these publish a few items a day."}],"coverage":{"search":"unconstrained","prefer":["complete","authoritative","accessible"],"mark_subscriber_links":true,"discovery_per_subtopic":false,"discovery_note":"Retired 2026-10-18 in favour of signal feeds and the per-source tally on the cuts page."},"editorial":{"two_axes":true,"summary_length":"2 to 4 sentences","summary_rule":"original prose, written from coverage the agent read; no verbatim passages beyond a short attributed quote","mark_thin_summaries":true},"evolution":{"mode":"propose"},"subtopic_scope_notes":{"finance-and-economics":"Give room to the financing of the AI build-out: debt loads at AI infrastructure companies, bond and credit-default-swap moves, hyperscaler capital spending, and the market''s exposure to it. Owner''s standing interest, 2026-10-17.","business":"Same emphasis as Finance and economics on the AI build-out and its risks, from the company side: capex, contracts, concentration, and who bears the losses if demand slows."},"source_roles":{"agenda":"Sets what is significant today. The editor ranks from these desks'' judgment. Three desks: the New York Times, the Economist, the Wall Street Journal.","signal":"Corroborates and widens the aperture. Items are candidates like any other, judged on consequence; a story only these feeds surfaced is the measure of what the agenda missed. Added 2026-10-17 to replace web-search discovery, after AP, Reuters and the BBC proved unreachable to the search tool. AP and Reuters publish no usable feed."}}', 'seed'
